<?php require __DIR__.'/../includes/bootstrap.php'; require_client();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT b.*,d.name drum_name,d.hourly_rate FROM bookings b JOIN drums d ON d.id=b.drum_id WHERE b.id=? AND b.user_id=?');$q->execute([$id,user()['id']]);$b=$q->fetch();if(!$b){http_response_code(404);page_header('Booking not found');echo '<div class="alert error">This booking does not exist or does not belong to your account.</div>';page_footer();exit;}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($b['status']!=='Pending')$error='Only pending bookings can be cancelled.';else{try{$s=db()->prepare("UPDATE bookings SET status='Cancelled' WHERE id=? AND user_id=? AND status='Pending'");$s->execute([$id,user()['id']]);flash('success','Booking cancelled.');redirect('index.php');}catch(Throwable $ex){error_log($ex->__toString());$error='Could not cancel booking. Please try again.';}}}
page_header('Booking details');?><div class="form-card"><div class="detail-head"><h2><?=e($b['drum_name'])?></h2><span class="<?=e(booking_status_class($b['status']))?>"><?=e($b['status'])?></span></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><dl class="details"><dt>Session date</dt><dd><?=e(date('F j, Y',strtotime($b['start_at'])))?></dd><dt>Time</dt><dd><?=e(date('g:i A',strtotime($b['start_at'])))?> – <?=e(date('g:i A',strtotime($b['end_at'])))?></dd><dt>Duration</dt><dd><?=(int)$b['duration_hours']?> hour(s)</dd><dt>Purpose</dt><dd><?=e($b['purpose'])?></dd><dt>Notes</dt><dd><?=nl2br(e($b['notes']?:'—'))?></dd><dt>Hourly rate</dt><dd><?=money($b['hourly_rate'])?></dd><dt>Total</dt><dd><strong><?=money($b['total_price'])?></strong></dd><dt>Requested</dt><dd><?=e(date('M j, Y g:i A',strtotime($b['created_at'])))?></dd><?php if($b['admin_note']):?><dt>Admin note</dt><dd><?=nl2br(e($b['admin_note']))?></dd><?php endif;?></dl><div class="actions"><a class="button secondary" href="index.php">Back</a><?php if($b['status']==='Pending'):?><form method="post" onsubmit="return confirm('Cancel this booking request?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button danger" type="submit">Cancel request</button></form><?php endif;?></div></div><?php page_footer();
